$nn = 0;
$total = count($datos);
$suma = 0;
$array = [];
foreach ($datos as $val) {

    $sql = Db::getInstance()->ExecuteS("select * from aalv_combinaciones_import aci where id_articulo = ".$val."
    UNION
    select * from aalv_combinacionunica_import aci2 where id_articulo = ".$val);
    if(count($sql) == 0){
        $array[] = $val;
        // dump($sql);die();
    }else{
        echo ".";
        $nn++;
    }

    if($nn == 100){
        $suma = $suma + 100;
        echo " => ".$total. " / ".$suma;
        echo "\n";
        $nn = 0;
    }


}

dump($array);